// DimCustomer — generated by src/powerbi/build_assets.py from DimCustomer.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimCustomer.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"customer_id", type text},
        {"customer_name", type text},
        {"customer_segment", type text},
        {"customer_region", type text},
        {"customer_country", type text},
        {"customer_type", type text},
        {"registration_date", type date},
        {"customer_status", type text},
        {"customer_lifetime_value", Currency.Type}
    }, "en-US")
in
    Typed
